const $=id=>document.getElementById(id);
const jobs=[['漁師','フィッシャー','⚓'],['エンジニア','エンジニア','▣'],['鉄工','アイアンワーカー','⚒'],['陶芸','ポッター','◈'],['美容','スタイリスト','✂'],['運送','ドライバー','▰'],['農家','ファーマー','♧'],['警察','ポリス','★'],['消防士','ファイアファイター','♨'],['建設','ビルダー','⌂']];
let records=[],current=null,photo='',stream=null,db,dirty=false;
const request=r=>new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function init(){try{const r=indexedDB.open('oshigoto-license-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');db=await request(r);records=await request(db.transaction('state').objectStore('state').get('participants'))||[];list()}catch(e){toast('保存機能を利用できません。ブラウザの設定を確認してください。');$('save').disabled=true;$('print').disabled=true}}
function persist(){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(records,'participants');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function toast(s){$('notice').textContent=s;$('notice').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('notice').style.display='none',4000)}
jobs.forEach((j,i)=>{const l=document.createElement('label');l.className='job';const c=document.createElement('input');c.type='checkbox';c.value=i;c.addEventListener('change',changed);l.append(c,document.createTextNode(j[2]+' '+j[0]));$('jobs').append(l)});
const selected=()=>[...$('jobs').querySelectorAll('input:checked')].map(x=>Number(x.value));
function changed(){dirty=true;render();$('save-state').textContent='変更内容は未保存です。「受付内容を保存」で保存できます。'}
function render(){ $('lic-name').textContent=$('nickname').value.trim()||'なまえ';$('lic-id').textContent=current?'ECH 2027-'+String(current).padStart(3,'0'):'受付前';$('lic-date').textContent=$('date').value.replaceAll('-',' / ');$('photo').replaceChildren();if(photo){const img=new Image();img.src=photo;img.style.objectPosition='50% '+$('pos').value+'%';img.style.transform='scale('+$('zoom').value+')';$('photo').append(img)}else $('photo').textContent='顔写真';const s=selected();$('qualifications').replaceChildren();jobs.forEach((j,i)=>{const d=document.createElement('div');d.className='qual'+(s.includes(i)?' earned':'');const label=document.createElement('span');label.textContent=j[2]+' ジュニア・'+j[1];const mark=document.createElement('b');mark.textContent=s.includes(i)?'認定 ✓':'—';d.append(label,mark);$('qualifications').append(d)});$('achievement').textContent='体験したお仕事 '+s.length+' / 10';$('issued').disabled=!current;}
function list(){ $('count').textContent='受付 '+records.length+' / 50名';$('people').replaceChildren();const query=$('search').value.trim();records.filter(r=>(String(r.id).padStart(3,'0')+' '+r.name).includes(query)).forEach(r=>{const b=document.createElement('button');b.className='person'+(r.id===current?' active':'');b.textContent=String(r.id).padStart(3,'0')+'　'+r.name+'　'+(r.issued?'✓ 渡し済':'未発行');b.onclick=()=>load(r);$('people').append(b)});$('new').disabled=records.length>=50}
function mayLeave(){return !dirty||confirm('未保存の変更を破棄して移動しますか？')}
function load(r){if(!mayLeave())return;current=r?.id||null;photo=r?.photo||'';$('nickname').value=r?.name||'';$('date').value=r?.date||'2027-03-07';$('zoom').value=r?.zoom||1;$('pos').value=r?.pos??50;[...$('jobs').querySelectorAll('input')].forEach(c=>c.checked=(r?.jobs||[]).includes(Number(c.value)));dirty=false;$('save-state').textContent=r?'保存済み：参加者 '+String(r.id).padStart(3,'0'):'新規受付：写真とニックネームを登録してください。';render();list()}
async function save(){const name=$('nickname').value.trim();if(!name){toast('ニックネームを入力してください');$('nickname').focus();return false}if(!photo){toast('写真を登録してください');return false}if(!$('date').value){toast('発行日を入力してください');return false}if(!current&&records.length>=50){toast('先着50名に達しています');return false}const before=records.slice(),old=current;const id=current||Math.max(0,...records.map(r=>r.id))+1;const prior=records.find(r=>r.id===id);const r={id,name,photo,date:$('date').value,zoom:Number($('zoom').value),pos:Number($('pos').value),jobs:selected(),issued:prior?.issued||false};records=records.filter(x=>x.id!==id).concat(r).sort((a,b)=>a.id-b.id);try{await persist();current=id;dirty=false;list();render();$('save-state').textContent='保存済み：参加者 '+String(id).padStart(3,'0');return true}catch(e){records=before;current=old;toast('保存に失敗しました。空き容量やブラウザの設定を確認してください');return false}}
async function setPhoto(file){if(!file)return;if(!file.type.startsWith('image/'))return toast('画像ファイルを選んでください');try{const url=URL.createObjectURL(file);const img=new Image();try{img.src=url;await img.decode();const c=document.createElement('canvas');const scale=Math.min(1,800/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);photo=c.toDataURL('image/jpeg',.85)}finally{URL.revokeObjectURL(url)}$('zoom').value=1;$('pos').value=50;changed()}catch{toast('画像を読み込めません。JPEG・PNGなどでお試しください')}}
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;$('camera-dialog').close()}
$('camera').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});$('video').srcObject=stream;$('camera-dialog').showModal()}catch{toast('カメラが使えません。「写真を選ぶ」から登録してください')}};
$('capture').onclick=()=>{const v=$('video');if(!v.videoWidth)return;const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(blob=>setPhoto(blob),'image/jpeg',.85);stopCamera()};$('close-camera').onclick=stopCamera;$('camera-dialog').addEventListener('cancel',stopCamera);
$('file').onchange=e=>setPhoto(e.target.files[0]);['nickname','date','zoom','pos'].forEach(id=>$(id).addEventListener('input',changed));$('search').oninput=list;$('new').onclick=()=>load(null);$('save').onclick=async()=>{if(await save())toast('保存しました')};$('size').onchange=()=>document.body.dataset.size=$('size').value;
$('print').onclick=async()=>{if(await save()){await Promise.all([...$('photo').querySelectorAll('img')].map(i=>i.decode()));window.print()}};
$('issued').onclick=async()=>{if(!await save())return;const r=records.find(x=>x.id===current),old=r.issued;r.issued=true;try{await persist();list();toast('受け渡し済みにしました')}catch{r.issued=old;toast('保存に失敗しました')}};
$('demo').onclick=()=>{if(!mayLeave())return;current=null;$('nickname').value='はる（見本）';$('date').value='2027-03-07';const c=document.createElement('canvas');c.width=300;c.height=400;const x=c.getContext('2d');x.fillStyle='#e5eef9';x.fillRect(0,0,300,400);x.fillStyle='#6388b5';x.beginPath();x.arc(150,135,62,0,Math.PI*2);x.fill();x.beginPath();x.ellipse(150,360,115,140,0,0,Math.PI*2);x.fill();photo=c.toDataURL();$('zoom').value=1;$('pos').value=50;[...$('jobs').querySelectorAll('input')].forEach((c,i)=>c.checked=[0,1,4,7].includes(i));changed();list();toast('見本を表示しました。まだ受付数には含まれません')};
$('delete').onclick=async()=>{if(!current)return toast('削除する参加者を選択してください');if(!confirm('この参加者の写真と情報を削除しますか？'))return;const old=records;records=records.filter(r=>r.id!==current);try{await persist();dirty=false;load(null);toast('削除しました')}catch{records=old;toast('削除できませんでした')}};
$('backup').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,records})],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='oshigoto-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('保存済みの参加者データを書き出しました')};
function valid(r){return r&&Number.isInteger(r.id)&&r.id>0&&typeof r.name==='string'&&r.name.trim().length>0&&r.name.length<=16&&typeof r.photo==='string'&&/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(r.photo)&&r.photo.length<2000000&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isFinite(r.zoom)&&r.zoom>=1&&r.zoom<=2.5&&Number.isFinite(r.pos)&&r.pos>=0&&r.pos<=100&&Array.isArray(r.jobs)&&r.jobs.every(i=>Number.isInteger(i)&&i>=0&&i<10)&&typeof r.issued==='boolean'}
$('restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.records)||data.records.length>50||!data.records.every(valid)||new Set(data.records.map(r=>r.id)).size!==data.records.length)throw Error();if(!confirm('現在の登録内容をバックアップの内容で置き換えますか？'))return;const old=records;records=data.records;try{await persist()}catch(err){records=old;throw err}dirty=false;load(null);toast('バックアップを読み込みました')}catch{toast('読み込みに失敗しました。バックアップ形式・保存容量を確認してください')}finally{e.target.value=''}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});render();init();
